    if (ejecutados.length === 0) {
      setFlashMessage('No se puede crear notificacion: la demanda no tiene ejecutados registrados.')
      return
    }

    const finalizeCreate = (ejecutadoId?: string) => {
      setCreatingDiligenciaId(diligencia.id)
      createNotificacion.mutate(
        { diligenciaId: diligencia.id, ejecutadoId },
        {
          onSuccess: createdNotificacion => {
            setFlashMessage(startImmediately ? 'Ejecucion iniciada.' : 'Nueva notificacion creada.')
            setCreatingDiligenciaId(null)
            if (startImmediately) openWizardForNotificacion(diligencia, createdNotificacion.id, 1)
          },
          onError: mutationError => {
            console.error('Error creando notificacion:', mutationError)
            setFlashMessage(mutationError.message || 'Error al crear notificacion. Intenta nuevamente.')
            setCreatingDiligenciaId(null)
          },
        }
      )
    }

    if (options?.ejecutadoId) return finalizeCreate(options.ejecutadoId)
    if (ejecutados.length === 1) return finalizeCreate(ejecutados[0].id)
    setEjecutadoModalOpen({ diligenciaId: diligencia.id, ejecutados, startImmediately })
    setSelectedEjecutadoId('')
  }

  const handleConfirmEjecutadoSelection = () => {
    if (!ejecutadoModalOpen || !selectedEjecutadoId) return
    const diligencia = sorted.find(item => item.id === ejecutadoModalOpen.diligenciaId)
    if (!diligencia) {
      setFlashMessage('No fue posible encontrar la diligencia seleccionada.')
      setEjecutadoModalOpen(null)
      setSelectedEjecutadoId('')
      return
    }
    setEjecutadoModalOpen(null)
    createNotificacionForDiligencia(diligencia, { ejecutadoId: selectedEjecutadoId, startImmediately: ejecutadoModalOpen.startImmediately })
    setSelectedEjecutadoId('')
  }

  const renderActionButton = (label: string, onClick: (event: MouseEvent<HTMLButtonElement>) => void, className: string, disabled = false) => (
    <button type="button" onClick={onClick} disabled={disabled} className={className}>{label}</button>
  )

  return (
    <section className="rounded-[28px] border border-slate-200/80 bg-[linear-gradient(180deg,#ffffff_0%,#f7f5ef_100%)] p-6 shadow-[0_24px_60px_-38px_rgba(15,23,42,0.45)]">
      <header className="flex flex-wrap items-center justify-between gap-4">
        <div className="space-y-1">
          <div className="inline-flex items-center gap-2 rounded-full border border-amber-200 bg-amber-50 px-3 py-1 text-[11px] font-semibold uppercase tracking-[0.24em] text-amber-700">
            Panel operativo
          </div>
          <div className="flex items-center gap-3">
            <h2 className="font-serif text-2xl text-slate-900">Diligencias</h2>
            {isLoading && (
              <span className="inline-flex items-center gap-2 text-xs text-slate-500">
                <span className="h-2 w-2 animate-ping rounded-full bg-slate-400" />
                Cargando...
              </span>
            )}
          </div>
          <p className="text-sm text-slate-600">
            Cada diligencia vive en su propio bloque para que ejecutar, recibo y estampo se lean de un vistazo.
          </p>
        </div>
        <button
          type="button"
          onClick={() => setShowWizard(true)}
          className="inline-flex items-center gap-2 rounded-full border border-slate-900 bg-slate-900 px-4 py-2.5 text-sm font-semibold text-white shadow-sm transition hover:-translate-y-0.5 hover:bg-slate-800"
        >
          <span className="text-base leading-none">+</span>
          Nueva diligencia
        </button>
      </header>

      {flashMessage && (
        <div className="mt-5 rounded-2xl border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm text-emerald-700">
          {flashMessage}
        </div>
      )}

      {isError && (
        <p className="mt-5 rounded-2xl border border-rose-200 bg-rose-50 px-4 py-3 text-sm text-rose-700">
          Error al obtener las diligencias: {error?.message ?? 'intenta nuevamente.'}
        </p>
      )}

      {!isLoading && !isError && sorted.length === 0 && (
        <div className="mt-5 rounded-[26px] border border-dashed border-slate-300 bg-white/80 px-6 py-10 text-center">
          <p className="text-base font-semibold text-slate-800">Aun no se han registrado diligencias para este ROL.</p>
          <p className="mt-2 text-sm text-slate-500">
            Crea la primera diligencia para empezar a ejecutar, generar recibos y trabajar estampos.
          </p>
        </div>
      )}

      {isLoading && (
        <div className="mt-6 space-y-4">
          {Array.from({ length: 3 }).map((_, index) => (
            <div
              key={`skeleton-${index}`}
              className="overflow-hidden rounded-[26px] border border-slate-200 bg-white/90 shadow-sm"
            >
              <div className="grid animate-pulse gap-px bg-slate-200 md:grid-cols-[1.4fr_1fr_0.9fr]">
                <div className="bg-stone-100 px-5 py-4">
                  <span className="mb-2 inline-block h-3 w-16 rounded-full bg-slate-200" />
                  <span className="block h-5 w-40 rounded bg-slate-200" />
                </div>
                <div className="bg-stone-100 px-5 py-4">
                  <span className="mb-2 inline-block h-3 w-24 rounded-full bg-slate-200" />
                  <span className="block h-5 w-32 rounded bg-slate-200" />
                </div>
                <div className="bg-stone-100 px-5 py-4">
                  <span className="mb-2 inline-block h-3 w-20 rounded-full bg-slate-200" />
                  <span className="block h-10 w-32 rounded-full bg-slate-200" />
                </div>
              </div>
              <div className="grid animate-pulse gap-px border-t border-slate-200 bg-slate-200 md:grid-cols-[1fr_1.4fr]">
                <div className="bg-white px-5 py-5">
                  <span className="mb-2 inline-block h-3 w-20 rounded-full bg-slate-200" />
                  <span className="block h-5 w-36 rounded bg-slate-200" />
                  <span className="mt-2 block h-4 w-48 rounded bg-slate-200" />
                </div>
                <div className="bg-white px-5 py-5">
                  <span className="mb-3 inline-block h-3 w-24 rounded-full bg-slate-200" />
                  <span className="block h-10 w-52 rounded-2xl bg-slate-200" />
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {!isLoading && !isError && sorted.length > 0 && (
        <div className="mt-6 space-y-4">
          {sorted.map(diligencia => {
            const notificaciones: VisibleNotificacion[] = (diligencia.notificaciones || [])
              .filter(notif => !notif.voidedAt)
              .slice()
              .sort((a, b) => {
                const aDate = a.createdAt ? new Date(a.createdAt).getTime() : Infinity
                const bDate = b.createdAt ? new Date(b.createdAt).getTime() : Infinity
                if (aDate !== bDate) return aDate - bDate
                return a.id.localeCompare(b.id)
              })
              .map(notif => {
                const meta = (notif.meta as Record<string, unknown> | null) ?? {}
                const estampoTipo = meta.estampoTipo
                const isEstampoTipoObject =
                  !!estampoTipo && typeof estampoTipo === 'object' && !Array.isArray(estampoTipo)
                const isWizard =
                  isEstampoTipoObject &&
                  (estampoTipo as { kind?: string }).kind === 'WIZARD' &&
                  typeof (estampoTipo as { categoria?: string }).categoria === 'string' &&
                  ((estampoTipo as { categoria?: string }).categoria?.length ?? 0) > 0
                const ejecutado = diligencia.ejecutados.find(item => item.id === notif.ejecutadoId)

                return {
                  ...notif,
                  _estampoLabel:
                    notif.latestEstampo?.nombreVisible ?? notif.latestEstampo?.slug ?? 'Sin estampo',
                  _ejecutadoNombre: ejecutado?.nombre ?? 'Ejecutado pendiente',
                  _ejecutadoDireccion:
                    ejecutado?.direccion ?? 'Selecciona el ejecutado para continuar con el flujo.',
                  _isWizard: isWizard,
                  _wizardCategoria: isWizard
                    ? ((estampoTipo as { categoria?: string }).categoria ?? null)
                    : null,
                }
              })
            const hasNotificaciones = notificaciones.length > 0
            const isCreating = creatingDiligenciaId === diligencia.id

            return (
              <article
                key={diligencia.id}
                className="overflow-hidden rounded-[26px] border border-slate-200 bg-white shadow-[0_18px_45px_-36px_rgba(15,23,42,0.55)]"
              >
                <div className="grid gap-px bg-slate-200 md:grid-cols-[1.45fr_1fr_0.95fr]">
                  <div className="bg-[linear-gradient(180deg,#fcfbf7_0%,#f7f2e8_100%)] px-5 py-4">
                    <div className="text-[11px] font-semibold uppercase tracking-[0.22em] text-slate-500">Tipo</div>
                    <div className="mt-2 flex flex-wrap items-center gap-3">
                      <div>
                        <div className="font-serif text-xl text-slate-900">{diligencia.tipo.nombre}</div>
                        {diligencia.tipo.descripcion && (
                          <div className="mt-1 text-sm text-slate-500">{diligencia.tipo.descripcion}</div>
                        )}
                      </div>
                      <span className="rounded-full border border-slate-200 bg-white px-2.5 py-1 text-[11px] font-medium uppercase tracking-[0.18em] text-slate-500">
                        {diligencia.estado}
                      </span>
                    </div>
                  </div>
                  <div className="bg-[linear-gradient(180deg,#fcfbf7_0%,#f9f6ef_100%)] px-5 py-4">
                    <div className="text-[11px] font-semibold uppercase tracking-[0.22em] text-slate-500">
                      Fecha Encargo
                    </div>
                    <div className="mt-2 text-base font-semibold text-slate-800">
                      {new Date(diligencia.fecha).toLocaleString('es-CL')}
                    </div>
                  </div>
                  <div className="bg-[linear-gradient(180deg,#f5f1e7_0%,#eee5d4_100%)] px-5 py-4">
                    <div className="text-[11px] font-semibold uppercase tracking-[0.22em] text-slate-500">
                      Acciones
                    </div>
                    <div className="mt-3 flex flex-wrap items-center justify-end gap-2">
                      {!hasNotificaciones ? (
                        <button
                          type="button"
                          onClick={() => createNotificacionForDiligencia(diligencia, { startImmediately: true })}
                          disabled={isCreating}
                          className="inline-flex min-h-12 items-center justify-center rounded-full border border-slate-900 bg-slate-900 px-5 py-3 text-sm font-semibold text-white shadow-sm transition hover:-translate-y-0.5 hover:bg-slate-800 disabled:cursor-not-allowed disabled:opacity-50"
                        >
                          {isCreating ? 'Preparando...' : 'Ejecutar'}
                        </button>
                      ) : (
                        <>
                          <span className="rounded-full border border-slate-300 bg-white/70 px-3 py-1 text-[11px] font-semibold uppercase tracking-[0.18em] text-slate-600">
                            {notificaciones.length} ciclo{notificaciones.length === 1 ? '' : 's'}
                          </span>
                          <button
                            type="button"
                            onClick={() => createNotificacionForDiligencia(diligencia)}
                            disabled={isCreating}
                            className="inline-flex items-center justify-center rounded-full border border-slate-300 bg-white px-4 py-2 text-sm font-semibold text-slate-700 transition hover:border-slate-400 hover:bg-slate-50 disabled:cursor-not-allowed disabled:opacity-50"
                          >
                            {isCreating ? 'Creando...' : 'Nuevo ciclo'}
                          </button>
                        </>
                      )}
                    </div>
                  </div>
                </div>
                {hasNotificaciones ? (
                  <div className="border-t border-slate-200">
                    <div className="grid gap-px bg-slate-200 md:grid-cols-[0.95fr_1.55fr]">
                      <div className="bg-slate-100 px-5 py-3 text-[11px] font-semibold uppercase tracking-[0.2em] text-slate-500">Ejecutado</div>
                      <div className="bg-slate-100 px-5 py-3 text-[11px] font-semibold uppercase tracking-[0.2em] text-slate-500">Acciones</div>
                    </div>
                    {notificaciones.map((notif, index) => (
                      <div key={notif.id} className={`grid gap-px bg-slate-200 md:grid-cols-[0.95fr_1.55fr] ${index === 0 ? '' : 'border-t border-slate-200'}`}>
                        <div className="bg-white px-5 py-5">
                          <div className="text-lg font-semibold text-slate-900">{notif._ejecutadoNombre}</div>
                          <div className="mt-1 text-sm leading-6 text-slate-500">{notif._ejecutadoDireccion}</div>
                          <div className="mt-4 flex flex-wrap items-center gap-2 text-xs text-slate-500">
                            <span>{notif.createdAt ? new Date(notif.createdAt).toLocaleString('es-CL') : 'Sin fecha de creacion'}</span>
                            {notif.latestEstampoId && (
                              <span className="rounded-full bg-emerald-50 px-2 py-1 font-medium text-emerald-700">Estampo listo</span>
                            )}
                          </div>
                        </div>
                        <div className="bg-white px-5 py-5">
                          {!notif.step1Done && (
                            <div className="flex flex-wrap items-start justify-between gap-4">
                              <div>
                                <div className="text-sm font-semibold uppercase tracking-[0.18em] text-slate-500">Acciones</div>
                                <p className="mt-2 max-w-xl text-sm leading-6 text-slate-500">Inicia la ejecucion de esta diligencia para capturar la visita y habilitar el recibo.</p>
                              </div>
                              {renderActionButton('Ejecutar', event => { event.stopPropagation(); openWizardForNotificacion(diligencia, notif.id, 1) }, 'inline-flex min-h-12 items-center justify-center rounded-full border border-amber-300 bg-amber-50 px-5 py-3 text-sm font-semibold text-amber-900 transition hover:bg-amber-100')}
                            </div>
                          )}
                          {notif.step1Done && !notif.step2Done && (
                            <div className="flex flex-wrap items-start justify-between gap-4">
                              <div>
                                <div className="text-sm font-semibold uppercase tracking-[0.18em] text-slate-500">Acciones</div>
                                <p className="mt-2 max-w-xl text-sm leading-6 text-slate-500">La ejecucion ya esta registrada. Continua con el recibo o vuelve a editar los datos previos.</p>
                              </div>
                              <div className="flex flex-wrap items-center gap-2">
                                {renderActionButton('Editar ejecucion', event => { event.stopPropagation(); openWizardForNotificacion(diligencia, notif.id, 1) }, 'rounded-full border border-slate-300 bg-white px-4 py-2 text-sm font-semibold text-slate-700 transition hover:border-slate-400 hover:bg-slate-50')}
                                {renderActionButton('Continuar con recibo', event => { event.stopPropagation(); openWizardForNotificacion(diligencia, notif.id, 2) }, 'rounded-full border border-blue-200 bg-blue-50 px-4 py-2 text-sm font-semibold text-blue-700 transition hover:bg-blue-100')}
                              </div>
                            </div>
                          )}
                          {notif.step2Done && (
                            <div className="grid gap-4 lg:grid-cols-2">
                              <div className="rounded-[22px] border border-amber-200 bg-[linear-gradient(180deg,#fffaf0_0%,#fff3d8_100%)] p-4">
                                <div className="text-[11px] font-semibold uppercase tracking-[0.18em] text-amber-700">For Estampo</div>
                                {!notif.step3Done ? (
                                  <>
                                    <p className="mt-2 text-sm leading-6 text-amber-900/80">El recibo ya fue generado. Ahora puedes continuar con el estampo de esta diligencia.</p>
                                    <div className="mt-4 flex flex-wrap gap-2">
                                      {renderActionButton('Continuar con estampo', event => { event.stopPropagation(); openEstampoEditor(diligencia, notif) }, 'rounded-full border border-amber-300 bg-white px-4 py-2 text-sm font-semibold text-amber-900 transition hover:bg-amber-50')}
                                    </div>
                                  </>
                                ) : (
                                  <>
                                    <div className="mt-2 text-lg font-semibold text-amber-950">{notif._estampoLabel}</div>
                                    <div className="mt-4 flex flex-wrap gap-2">
                                      {notif.latestEstampoId && renderActionButton('Ver estampo', event => handleViewDocumento(event, notif.latestEstampoId!), 'rounded-full border border-emerald-200 bg-emerald-50 px-4 py-2 text-sm font-semibold text-emerald-700 transition hover:bg-emerald-100')}
                                      {renderActionButton('Editar', event => { event.stopPropagation(); openEstampoEditor(diligencia, notif) }, 'rounded-full border border-amber-300 bg-white px-4 py-2 text-sm font-semibold text-amber-900 transition hover:bg-amber-50')}
                                    </div>
                                  </>
                                )}
                              </div>
                              <div className="rounded-[22px] border border-sky-200 bg-[linear-gradient(180deg,#f6fbff_0%,#eaf5ff_100%)] p-4">
                                <div className="text-[11px] font-semibold uppercase tracking-[0.18em] text-sky-700">Recibo</div>
                                <p className="mt-2 text-sm leading-6 text-sky-950/75">El recibo ya forma parte del flujo. Puedes verlo o volver al paso correspondiente.</p>
                                <div className="mt-4 flex flex-wrap gap-2">
                                  {renderActionButton('Editar recibo', event => { event.stopPropagation(); openWizardForNotificacion(diligencia, notif.id, 2) }, 'rounded-full border border-sky-300 bg-white px-4 py-2 text-sm font-semibold text-sky-800 transition hover:bg-sky-50')}
                                  {notif.latestBoletaId && renderActionButton('Ver recibo', event => handleViewDocumento(event, notif.latestBoletaId!), 'rounded-full border border-emerald-200 bg-emerald-50 px-4 py-2 text-sm font-semibold text-emerald-700 transition hover:bg-emerald-100')}
                                </div>
                              </div>
                            </div>
                          )}
                          <div className="mt-5 flex justify-end">
                            {renderActionButton('Anular', event => {
                              event.stopPropagation()
                              const ok = window.confirm('Anular esta notificacion? Los documentos asociados tambien seran anulados y ocultados de la vista normal. Esta accion puede revertirse en el futuro para auditoria.')
                              if (!ok) return
                              deleteNotificacion.mutate(
                                { diligenciaId: diligencia.id, notificacionId: notif.id },
                                { onSuccess: () => setFlashMessage('Notificacion anulada.'), onError: mutationError => setFlashMessage(mutationError.message || 'Error al anular notificacion') }
                              )
                            }, 'rounded-full border border-rose-200 bg-rose-50 px-4 py-2 text-sm font-semibold text-rose-700 transition hover:bg-rose-100 disabled:cursor-not-allowed disabled:opacity-50', deleteNotificacion.isPending)}
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                ) : (
                  <div className="grid gap-px border-t border-slate-200 bg-slate-200 md:grid-cols-[0.95fr_1.55fr]">
                    <div className="bg-slate-100 px-5 py-3 text-[11px] font-semibold uppercase tracking-[0.2em] text-slate-500">Ejecutado</div>
                    <div className="bg-slate-100 px-5 py-3 text-[11px] font-semibold uppercase tracking-[0.2em] text-slate-500">Acciones</div>
                    <div className="bg-white px-5 py-5"><div className="text-lg font-semibold text-slate-700">Pendiente de definir</div><div className="mt-1 text-sm leading-6 text-slate-500">El ejecutado se asociara cuando inicies la ejecucion de esta diligencia.</div></div>
                    <div className="bg-white px-5 py-5"><div className="rounded-[22px] border border-dashed border-slate-300 bg-slate-50 px-4 py-4"><div className="text-sm font-semibold uppercase tracking-[0.18em] text-slate-500">Acciones</div><p className="mt-2 max-w-xl text-sm leading-6 text-slate-500">Todavia no existe un ciclo para esta diligencia. Usa el boton superior para ejecutar y abrir el flujo normal.</p></div></div>
                  </div>
                )}
              </article>
            )
          })}
        </div>
      )}

      {showWizard && (
        <NuevaDiligenciaWizard
          rolId={rolId}
          onClose={() => setShowWizard(false)}
          onCreated={() => setFlashMessage('Diligencia creada correctamente.')}
        />
      )}

      {ejecutarTarget && ejecutarNotificacionId && (
        <EjecutarWizard
          rolId={rolId}
          diligencia={ejecutarTarget}
          notificacionId={ejecutarNotificacionId}
          initialStep={ejecutarInitialStep}
          onClose={() => {
            setEjecutarTarget(null)
            setEjecutarNotificacionId(null)
            setEjecutarInitialStep(undefined)
          }}
          onSuccess={() => {
            setFlashMessage(`Ejecucion completada para ${ejecutarTarget.tipo.nombre}.`)
            setEjecutarTarget(null)
            setEjecutarNotificacionId(null)
            setEjecutarInitialStep(undefined)
          }}
          onOpenWizard={(diligenciaId, categoria, notificacionId) => {
            setWizardModalOpen({ diligenciaId, categoria, notificacionId })
          }}
        />
      )}

